/bin/bash -lc "python - <<'PY'
from pathlib import Path
files = [
'/home/lixinyu/snap/new/ARC_code/eval/16b78196.py',
'/home/lixinyu/snap/new/ARC_code/eval/58490d8a.py',
'/home/lixinyu/snap/new/ARC_code/train/df9fd884.py',
'/home/lixinyu/snap/new/ARC_code/eval/d8e07eb2.py',
]
for path in files:
    print(f'===== {path} =====')
    lines = Path(path).read_text().splitlines()
    idxs = []
    for i,l in enumerate(lines):
        if l.startswith('def main(') or l.startswith('def generate_input('):
            idxs.append(i)
    for idx in idxs:
        end = min(len(lines), idx + 90)
        print(f'--- lines {idx+1}-{end} ---')
        for j in range(idx, end):
            print(f'{j+1:4}: {lines[j]}')
